// GENERATED by functions/build-single.js from functions/login-code/index.ts + _shared (supabase.ts, login.ts). Do not edit: edit those and run it again.
import { createClient, SupabaseClient } from "npm:@supabase/supabase-js@2.45.4";

// ---------- from _shared/supabase.ts ----------
// Shared helpers for the Wellbe edge functions (Deno). Keys come from Supabase secrets, never from code.

const URL = Deno.env.get("SUPABASE_URL")!;
const ANON = Deno.env.get("SUPABASE_ANON_KEY")!;
const SERVICE = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;   // only inside functions, never in the apps

// a client that acts as the caller (their Supabase Auth login), so Row Level Security applies
function asCaller(req: Request): SupabaseClient {
  return createClient(URL, ANON, { global: { headers: { Authorization: req.headers.get("Authorization") ?? "" } }, auth: { persistSession: false } });
}
// a client with full access: workers, and the API door (which checks the caller itself)
function asService(): SupabaseClient {
  return createClient(URL, SERVICE, { auth: { persistSession: false } });
}

// pages allowed to call the API from a browser: the live apps and local testing
const ORIGINS = (Deno.env.get("ALLOWED_ORIGINS") ?? "https://majd-wellbe.github.io").split(",").map((s) => s.trim()).filter(Boolean);
function allowedOrigin(origin: string | null): string | null {
  if (!origin) return null;
  if (ORIGINS.includes(origin)) return origin;
  if (/^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(origin)) return origin;
  if (origin === "capacitor://localhost" || origin === "https://localhost" || origin === "ionic://localhost") return origin;   // the store apps (Capacitor)
  return null;
}
function corsFor(req: Request): Record<string, string> {
  const o = allowedOrigin(req.headers.get("Origin"));
  return { ...(o ? { "Access-Control-Allow-Origin": o } : {}), "Vary": "Origin",
    "Access-Control-Allow-Methods": "POST, OPTIONS", "Access-Control-Allow-Headers": "authorization, content-type, apikey, x-client-info" };
}
function jsonFor(req: Request, body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...corsFor(req), "Content-Type": "application/json" } });
}

// older helpers, still used by the workers and upload
const cors = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "authorization, content-type, apikey, x-client-info" };
function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { ...cors, "Content-Type": "application/json" } });
}

// ---------- from _shared/login.ts ----------
// Sign in with a 6 digit email code, exactly like Client.gs clCode_ / clLogin_ today.
// Codes, limits and sessions live in the database (migrations/0008_auth.sql). This file only sends the email.
// Secrets: RESEND_API_KEY, MAIL_FROM (e.g. "Wellbe Health Center <app@wellbe...>", a domain verified in Resend).

type R = Record<string, unknown>;
const esc = (s: string) => s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]!));

function codeEmail(first: string, code: string) {
  const f = esc(first || "");
  return {
    subject: "Your Wellbe code: " + code,
    text: "Hi " + first + ",\n\nYour Wellbe app code is " + code + "\nIt works for 10 minutes.\n\nDid not ask for it? Ignore this email.\n\nWellbe Health Center",
    html: '<div style="font-family:Arial,sans-serif;max-width:420px;margin:auto;padding:24px;color:#151b1e">' +
      '<div style="font-size:22px;font-weight:800;letter-spacing:2px;color:#1f6e5b">WELLBE</div>' +
      '<p style="font-size:16px">Hi ' + f + ", here is your code:</p>" +
      '<div style="font-size:36px;font-weight:800;letter-spacing:8px;background:#e9f6f2;border-radius:12px;padding:16px;text-align:center">' + code + "</div>" +
      '<p style="color:#5b6b70;font-size:14px">It works for 10 minutes. Did not ask for it? Just ignore this email.</p></div>',
  };
}

async function sendMail(to: string, m: { subject: string; text: string; html: string }, fetcher: typeof fetch = fetch): Promise<boolean> {
  const key = Deno.env.get("RESEND_API_KEY"), from = Deno.env.get("MAIL_FROM");
  if (!key || !from) { console.error("RESEND_API_KEY or MAIL_FROM missing"); return false; }
  try {
    const r = await fetcher("https://api.resend.com/emails", {
      method: "POST", headers: { Authorization: "Bearer " + key, "Content-Type": "application/json" },
      body: JSON.stringify({ from, to: [to], subject: m.subject, text: m.text, html: m.html }),
    });
    if (!r.ok) console.error("Resend " + r.status + " " + (await r.text()).slice(0, 300));
    return r.ok;
  } catch (e) { console.error("Resend " + e); return false; }
}

const rpc = async (db: SupabaseClient, fn: string, args: R): Promise<R> => {
  const { data, error } = await db.rpc(fn, args);
  if (error) return { ok: false, error: error.message };
  return (data ?? { ok: false, error: "Server error" }) as R;
};

// app_cl_code {email, mode, name}
async function askCode(db: SupabaseClient, b: R, fetcher: typeof fetch = fetch, desk = "the front desk"): Promise<R> {
  const r = await rpc(db, "wb_login_code", { p_email: String(b.email ?? ""), p_mode: b.mode ?? null, p_name: b.name ?? null });
  if (!r.ok) return r;
  const email = String(r.email ?? b.email ?? "").trim().toLowerCase(), code = String(r.code);
  const sent = await sendMail(email, codeEmail(String(r.first ?? ""), code), fetcher);
  if (!sent) {
    await rpc(db, "wb_login_code_cancel", { p_email: email });
    return { ok: false, error: "We could not send the email right now. Try again in a few minutes, or message " + String(r.desk ?? desk) + " on WhatsApp." };
  }
  const out: R = { ok: true };
  if (r.guest) out.guest = true;
  if (r.client) out.client = true;
  return out;                                   // never the code
}

// app_cl_login {email, code} -> {ok, token}
function verifyCode(db: SupabaseClient, b: R): Promise<R> {
  return rpc(db, "wb_login_verify", { p_email: String(b.email ?? ""), p_code: String(b.code ?? "") });
}

// ---------- the function ----------
// =====================================================================
// Sign in with a 6 digit email code (same as Client.gs clCode_ / clLogin_ today).
// The api function already handles app_cl_code and app_cl_login; this one exists for pages that only sign in.
//   POST {email, mode?, name?}        -> sends the code       {ok, guest?, client?}
//   POST {email, code}                -> checks it            {ok, token}
// Own codes (not Supabase Auth OTP): see migrations/0008_auth.sql header for why.
// =====================================================================

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsFor(req) });
  const b = await req.json().catch(() => null);
  if (!b || typeof b !== "object") return jsonFor(req, { ok: false, error: "Bad request" }, 400);
  const db = asService();
  return jsonFor(req, b.code != null ? await verifyCode(db, b) : await askCode(db, b));
});
